async function loadMonth(month){const target=view().querySelector('[data-month-detail]');target.innerHTML='<p>Loading scoresheet…</p>';try{const detail=(await api('/me/profile/months/'+encodeURIComponent(month))).profile.month;target.innerHTML=`<div class="profile-card" style="margin-top:14px"><h3>${h(monthLabel(month))} · Total ${h(detail.official_total??'—')}</h3><div class="profile-breakdown">${components(detail)}</div></div>`;}catch(error){target.innerHTML=`<div class="profile-alert error">${h(error.message)}</div>`;}}
