function renderRequestForm(kind){const day=state.selectedDay,entries=day.entries||[];const entryField=kind==='incorrect_entry'?`<label>Entry<select name="entry">${entries.map((entry,index)=>`<option value="${index}">${h(entry.points)} points · ${h(entry.note)}</option>`).join('')}</select></label>`:'';const pointsField=kind==='missing_score'?'<label>Expected points, if known<input name="claimed_points" type="number" step="1"></label>':'';const transferFields=kind==='transfer_request'?'<label>Find recipient<input data-recipient-search placeholder="Roll number or name" autocomplete="off"></label><div class="profile-recipient-results" data-recipient-results></div><label>Transfer type<select name="transfer_type"><option value="points">Points</option><option value="stars">Stars</option></select></label><label>Amount<input name="amount" type="number" min="1" max="50" required></label>':'';sheet().querySelector('[data-day-form]').innerHTML=`<form class="profile-form" data-request-form><h3>${h(label(kind))}</h3>${entryField}${pointsField}${transferFields}<label>Explain the request<textarea name="message" maxlength="2000" required></textarea></label><button class="profile-btn" type="submit">Send to Admin</button></form>`;const form=sheet().querySelector('[data-request-form]');form.onsubmit=event=>submitRequest(event,kind);const search=form.querySelector('[data-recipient-search]');if(search)search.oninput=debounce(()=>searchRecipients(search.value),250);}
async function searchRecipients(query){const target=sheet().querySelector('[data-recipient-results]');state.selectedRecipient=null;if(query.trim().length<2){target.innerHTML='';return;}try{const data=await api('/me/transfer-recipients?q='+encodeURIComponent(query));target.innerHTML=data.recipients.map(row=>`<button type="button" class="profile-recipient" data-recipient="${h(row.student_id)}"><strong>${h(row.login_id)}</strong> · ${h(row.display_name)} · Class ${h(row.class_label||'—')}</button>`).join('')||'<small>No active recipient found.</small>';target.querySelectorAll('[data-recipient]').forEach(button=>button.onclick=()=>{state.selectedRecipient=data.recipients.find(row=>String(row.student_id)===button.dataset.recipient);target.querySelectorAll('button').forEach(item=>item.classList.toggle('selected',item===button));});}catch(error){target.innerHTML=`<small>${h(error.message)}</small>`;}}
async function submitRequest(event,kind){event.preventDefault();const form=event.currentTarget,data=new FormData(form),day=state.selectedDay,payload={kind,target_date:day.date,message:String(data.get('message')||''),client_request_id:crypto.randomUUID(),context_version:state.profile.current_month_detail.content_version};if(kind==='missing_score'&&data.get('claimed_points')!=='')payload.claimed_points=Number(data.get('claimed_points'));if(kind==='incorrect_entry'){const entry=day.entries[Number(data.get('entry'))];payload.target_entry_ref=entry.entry_ref;payload.target_entry_digest=entry.content_digest;}if(kind==='transfer_request'){if(!state.selectedRecipient){notice('Select a recipient first.',true);return;}payload.transfer={recipient_student_id:String(state.selectedRecipient.student_id),transfer_type:String(data.get('transfer_type')),amount:Number(data.get('amount'))};}const button=form.querySelector('button[type=submit]');button.disabled=true;try{await api('/me/requests',{method:'POST',body:JSON.stringify(payload)});closeSheet();state.view='requests';await loadRequests();notice('Request sent. Admin replies will appear here.');}catch(error){notice(error.message,true);button.disabled=false;}}
