async function logout(){sessionGeneration++;try{if(!state.csrf)state.csrf=(await api('/auth/csrf')).csrf_token;await api('/auth/logout',{method:'POST'});}catch(error){notice('Sign out could not be confirmed. Please retry.',true);return false;}sessionStorage.removeItem(CSRF_KEY);state.csrf='';state.profile=null;state.workspace=null;state.account=null;state.requestRows=[];window.dispatchEvent(new CustomEvent('ea-portal-session',{detail:null}));stopDelivery();authScreen('login');return true;}
function profileVisible(){const panel=document.getElementById('myProfilePanel');return !document.hidden&&(!panel||panel.classList.contains('active'));}
function connectNotifications(){if(!deliveryActive||!profileVisible())return;try{const protocol=location.protocol==='https:'?'wss:':'ws:';const socket=new WebSocket(protocol+'//'+location.host+API+'/me/notifications/socket');state.socket=socket;socket.onopen=()=>{if(state.socket===socket){nextNotificationCheck=Date.now()+300000;pollNotifications();}};socket.onmessage=()=>pollNotifications();socket.onclose=()=>{if(state.socket!==socket||!deliveryActive)return;state.socket=null;nextNotificationCheck=Date.now()+60000;socketReconnect=setTimeout(connectNotifications,60000);};socket.onerror=()=>{try{socket.close();}catch{}};}catch{socketReconnect=setTimeout(connectNotifications,60000);}}
function startDelivery(){stopDelivery();if(!profileVisible()||Date.now()<quotaRetryAt)return;deliveryActive=true;nextNotificationCheck=Date.now()+60000;pollNotifications();state.poll=setInterval(()=>{if(profileVisible()&&Date.now()>=nextNotificationCheck){nextNotificationCheck=Date.now()+(state.socket?.readyState===1?300000:60000);pollNotifications();}},60000);connectNotifications();}
function stopDelivery(){deliveryActive=false;if(socketReconnect)clearTimeout(socketReconnect);socketReconnect=null;if(chatTimer){clearInterval(chatTimer);chatTimer=null;}if(state.poll)clearInterval(state.poll);state.poll=null;const socket=state.socket;state.socket=null;if(socket){socket.onclose=null;try{socket.close();}catch{}}}
async function pollNotifications(){if(notificationBusy||!profileVisible()||Date.now()<quotaRetryAt)return;notificationBusy=true;const generation=sessionGeneration,owner=String(state.account?.student_id||state.account?.staff_id||'');try{const key=CURSOR_KEY+':'+owner,after=sessionStorage.getItem(key)||'0',data=await api('/me/notifications?after='+encodeURIComponent(after));if(generation!==sessionGeneration)return;sessionStorage.setItem(key,String(data.cursor||after));if(data.notifications?.length){await loadRequests(false);if(state.view==='requests')renderRequests();notice(`${data.notifications.length} request update${data.notifications.length===1?'':'s'} received.`);}}catch{}finally{notificationBusy=false;}}
function resumeDelivery(){if(!profileVisible()){stopDelivery();return;}if(state.account&&(state.profile||state.account.kind==='staff')&&!deliveryActive){if(state.account.kind!=='staff')startDelivery();if(state.view==='chat')renderChat();}}
