function debounce(fn,wait){let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>fn(...args),wait);};}
function renderChat(){
  const rooms=state.workspace?.chat_rooms||[];
  if(!rooms.includes(chatRoom))chatRoom=rooms[0]||'general';
  view().innerHTML=`<div class="profile-chat-head"><div><h3>${h(chatRoom==='council'?'Student Council':'General Chat')}</h3><small>Messages are monitored under the academy rules.</small></div><div class="profile-actions">${rooms.map(room=>`<button type="button" class="profile-btn ${room===chatRoom?'':'secondary'}" data-chat-room="${h(room)}">${h(room==='council'?'Student Council':'General')}</button>`).join('')}</div></div><div class="profile-list" data-chat-messages aria-live="polite"><p>Loading messages…</p></div><div class="profile-alert" data-chat-error hidden></div>${state.account?.kind==='staff'?'':`<form class="profile-form" data-chat-form><label>Message<textarea name="message" maxlength="1500" required></textarea></label><button class="profile-btn" type="submit">Send message</button></form>`}`;
  view().querySelectorAll('[data-chat-room]').forEach(button=>button.onclick=()=>{chatRoom=button.dataset.chatRoom;chatRows=[];renderChat();});
  view().querySelector('[data-chat-form]')?.addEventListener('submit',sendChat);
  loadChat();
  if(!chatTimer)chatTimer=setInterval(()=>{if(state.view==='chat'&&profileVisible())loadChat();},60000);
}
async function loadChat(){
  if(chatBusy||!profileVisible()||Date.now()<quotaRetryAt)return;
  chatBusy=true;
  const room=chatRoom;
  try{
    const data=await api('/chat/'+room+'/messages');
    if(state.view!=='chat'||chatRoom!==room){chatBusy=false;return;}
    chatRows=data.messages||[];
    const target=view().querySelector('[data-chat-messages]');
    target.innerHTML=chatRows.map(row=>`<article class="profile-chat-message ${row.pinned?'pinned':''} ${row.highlighted?'highlighted':''}"><div class="profile-chat-meta"><strong>${h(row.login_id)}</strong><small>${h(new Date(row.created_at).toLocaleString())}</small>${row.pinned?'<span class="profile-status">Pinned</span>':''}${row.highlighted?'<span class="profile-status">Highlighted</span>':''}</div><p>${row.hidden?'<em>Message hidden by a moderator.</em>':h(row.body)}</p>${row.can_moderate?`<div class="profile-actions"><button type="button" class="profile-btn secondary" data-chat-action="hide" data-chat-id="${h(row.message_id)}">Hide</button>${data.moderator!=='co_leader'?`<button type="button" class="profile-btn secondary" data-chat-action="${row.pinned?'unpin':'pin'}" data-chat-id="${h(row.message_id)}">${row.pinned?'Unpin':'Pin'}</button><button type="button" class="profile-btn secondary" data-chat-action="${row.highlighted?'unhighlight':'highlight'}" data-chat-id="${h(row.message_id)}">${row.highlighted?'Remove highlight':'Highlight'}</button>`:''}<button type="button" class="profile-btn secondary" data-chat-restrict="${h(row.student_id)}">Restrict chat</button></div>`:''}</article>`).join('')||'<p>No messages yet.</p>';
    target.querySelectorAll('[data-chat-action]').forEach(button=>button.onclick=()=>moderateChat(button.dataset.chatId,button.dataset.chatAction));
    target.querySelectorAll('[data-chat-restrict]').forEach(button=>button.onclick=()=>restrictChat(button.dataset.chatRestrict));
    view().querySelector('[data-chat-error]').hidden=true;
  }catch(error){
    if(error.message==='database_daily_quota_exceeded'){serviceUnavailable(error);return;}
    if(state.view!=='chat'||chatRoom!==room||!view())return;
    const alert=view().querySelector('[data-chat-error]');alert.textContent=error.message;alert.hidden=false;
    if(error.status===403){view().querySelector('[data-chat-messages]').innerHTML='<p>Chat access is currently unavailable.</p>';view().querySelector('[data-chat-form]')?.remove();}
  }finally{chatBusy=false;if(chatRoom!==room&&state.view==='chat'&&profileVisible())setTimeout(loadChat,0);}
}
async function sendChat(event){
  event.preventDefault();
  const form=event.currentTarget,button=form.querySelector('button[type=submit]'),message=String(new FormData(form).get('message')||'').trim();
  if(!message)return;
  button.disabled=true;
  try{await api('/chat/'+chatRoom+'/messages',{method:'POST',body:JSON.stringify({message,client_message_id:crypto.randomUUID()})});form.reset();await loadChat();}
  catch(error){notice(error.message,true);}
  finally{button.disabled=false;}
}
async function moderateChat(id,action){
  const reason=action==='hide'?prompt('Reason for hiding this message:'):'';
  if(action==='hide'&&!reason)return;
  try{await api('/chat/'+chatRoom+'/messages/'+encodeURIComponent(id)+'/moderate',{method:'POST',body:JSON.stringify({action,reason})});await loadChat();}
  catch(error){notice(error.message,true);}
}
async function restrictChat(studentId){
  const duration=prompt('Restrict chat for how many hours? Leader: up to 24; Co-Leader: 1; Admin: up to 720.','1');
  if(duration===null)return;
  const reason=prompt('Reason for this chat restriction:');
  if(!reason)return;
  try{await api('/chat/restrictions',{method:'POST',body:JSON.stringify({student_id:studentId,duration_hours:Number(duration),reason})});notice('Chat restriction recorded.');await loadChat();}
  catch(error){notice(error.message,true);}
}
